-- 1. 先确认表行数与统计信息（只读）：
SELECT TABLE_NAME, TABLE_ROWS, UPDATE_TIME FROM information_schema.TABLES WHERE TABLE_SCHEMA = '<DB>' AND TABLE_NAME = '<TABLE>';
-- 2. 建议非高峰执行（谨慎）：
-- DANGER: ANALYZE TABLE `<DB>`.`<TABLE>`;

-- 1. 先确认（只读）：
SELECT ID, USER, HOST, DB, COMMAND, TIME, STATE, LEFT(INFO, 200) AS SQL_TEXT FROM information_schema.PROCESSLIST WHERE ID = <ID>;
-- 2. 确认无误后再执行（危险）：
-- DANGER: KILL <ID>;
-- 只杀查询、不断连接可用：-- DANGER: KILL QUERY <ID>;

-- 1. 先确认 binlog 与备份窗口（只读）：
SHOW BINARY LOGS;
SHOW GLOBAL VARIABLES LIKE 'binlog_expire_logs_seconds';
-- 2. 恢复为危险操作：PolarDB 无 SQL 恢复命令，在控制台按备份集 + 时间点恢复，优先恢复到新实例、核对后再切换；恢复前先在测试集群完整演练一次：
-- DANGER: 控制台 > 备份恢复 > 按时间点恢复到新实例（勿直接覆盖原集群）；

SELECT VERSION() AS version;
SHOW GLOBAL VARIABLES LIKE 'read_only';
SHOW FULL PROCESSLIST;
